parameters.jsCode:
// ─────────────────────────────────────────────────────
// NODE: Parse Visitor Payload
//
// Normalises payloads from multiple de-anonymisation tools:
//   Salesbox AI, RB2B, Clearbit Reveal, Albacross, Leadfeeder, Koala, etc.
//
// Expected shape (Salesbox AI):
// {
//   event: 'visitor.identified',
//   visitor: {
//     id, identified_at,
//     contact:  { first_name, last_name, email, linkedin_url, job_title, location },
//     company:  { name, domain, employee_count, industry, funding_stage },
//     session:  { page_url, page_title, referrer, started_at, duration_seconds },
//     intent_score: 0-100,
//     intent_signals: ['pricing_page', ...]
//   }
// }
//
// Also handles RB2B ({ person: {...} }), Clearbit ({ company: {...}, person: {...} })
// and generic flat payloads.
// ─────────────────────────────────────────────────────
const body = $input.first().json;

const raw     = body.visitor || body;
const contact = raw.contact  || raw.person  || raw.profile || body.person || {};
const company = raw.company  || raw.organization || body.company || {};
const session = raw.session  || raw.page    || raw.pageView || {};

// ── Resolve LinkedIn URL from any tool's schema ──────
const linkedInUrl =
  contact.linkedin_url  ||
  contact.linkedInUrl   ||
  contact.linkedin      ||
  contact.linkedinUrl   ||
  raw.linkedin_url      ||
  '';

const visitor = {
  // Source tool identity (useful for routing logic downstream)
  sourceEvent:    body.event || body.type || 'visitor.identified',
  sourceTool:     body.source || body.integration || 'unknown',

  // Visitor / contact fields
  visitorId:      raw.id || raw.visitor_id || '',
  firstName:      contact.first_name  || contact.firstName  || '',
  lastName:       contact.last_name   || contact.lastName   || '',
  fullName:       contact.full_name   || contact.name       ||
                  `${contact.first_name || ''} ${contact.last_name || ''}`.trim(),
  email:          contact.email       || '',
  linkedInUrl,
  linkedInId:     contact.linkedin_id  || contact.linkedInId  || '',
  title:          contact.job_title   || contact.title       || contact.jobTitle || '',
  location:       contact.location    || contact.city        || '',

  // Company fields
  companyName:    company.name        || contact.company    || '',
  companyDomain:  company.domain      || company.website    || '',
  companySize:    company.employee_count || company.employeeCount || company.headcount || company.size || '',
  industry:       company.industry    || '',
  fundingStage:   company.funding_stage || company.fundingStage || '',

  // Session / page fields
  pageUrl:        session.page_url    || session.url        || body.url   || raw.page_url || '',
  pageTitle:      session.page_title  || session.title      || body.title || raw.page_title || '',
  referrer:       session.referrer    || '',
  sessionDuration: session.duration_seconds || session.durationSeconds || 0,
  visitedAt:      raw.identified_at  || session.started_at ||
                  body.timestamp     || new Date().toISOString(),

  // Intent fields (Salesbox AI / Koala / common)
  intentScore:    raw.intent_score   || raw.intentScore    || 0,
  intentSignals:  (raw.intent_signals || raw.intentSignals || []).join(', '),

  _raw: body
};

if (!visitor.linkedInUrl && !visitor.email) {
  throw new Error('SKIP: No LinkedIn URL or email found — cannot reach out.');
}

if (!visitor.firstName) {
  visitor.firstName = 'there';
}

return [{ json: visitor }];

const visitor  = $('Page Filter (Customise Me)').first().json;
const apolloRaw = $input.first().json;
const person   = apolloRaw?.person || {};
const org      = apolloRaw?.organization || {};

const enriched = {
  ...visitor,
  firstName:      person.first_name    || visitor.firstName,
  lastName:       person.last_name     || visitor.lastName,
  fullName:       person.name          || visitor.fullName,
  email:          person.email         || person.personal_emails?.[0] || visitor.email,
  linkedInUrl:    person.linkedin_url  || visitor.linkedInUrl,
  title:          person.title         || visitor.title,
  seniorityLevel: person.seniority     || '',
  departments:    (person.departments  || []).join(', '),
  companyName:    org.name             || visitor.companyName,
  companyDomain:  org.primary_domain   || visitor.companyDomain,
  companySize:    org.num_employees    || visitor.companySize,
  industry:       org.industry         || visitor.industry,
  fundingStage:   org.latest_funding_stage || visitor.fundingStage,
  apolloId:       person.id            || '',
};

// ── Build contextual identifiers ─────────────────────
const companyCtx  = enriched.companyName ? ` at ${enriched.companyName}` : '';
const titleCtx    = enriched.title ? `, ${enriched.title}${companyCtx}` : companyCtx;
const pageName    = enriched.pageTitle || enriched.pageUrl.split('/').filter(Boolean).pop() || 'our site';

// ── Personalised outreach scripts (generic, page-aware) ──
enriched.voiceNoteScript =
  `Hey ${enriched.firstName}${titleCtx} — I noticed you were checking out ${pageName} today. ` +
  `I'd love to quickly walk you through how teams like yours are using us — I can keep it to 15 minutes and make it worth your while. Would that be useful?`;

enriched.connectionMessage =
  `Hi ${enriched.firstName}, I saw you were exploring ${pageName} — thought it was worth connecting in case you had any questions or wanted some context. No agenda, just happy to help.`;

enriched.followUpMessage =
  `Hey ${enriched.firstName} — following up on my voice note from yesterday. ` +
  `Would a 15-min call this week make sense? Happy to tailor the conversation to what matters most for ${enriched.companyName || 'your team'}.`;

return [{ json: enriched }];

