Updates existing contact by HubSpot ID.
Endpoint: PATCH https://api.hubapi.com/crm/v3/objects/contacts/{id}
Docs: https://developers.hubspot.com/docs/api/crm/contacts

parameters.jsCode:
let contactId;
let isNew = false;

try {
  const created = $('HubSpot: Create Contact').first().json;
  if (created?.id) { contactId = created.id; isNew = true; }
} catch (e) {}

if (!contactId) {
  try {
    const search = $('HubSpot: Search Contact').first().json;
    contactId = search?.results?.[0]?.id;
  } catch (e) {}
}

const visitor = $('Build Personalised Messages').first().json;
return [{ json: { ...visitor, hubspotContactId: contactId || null, isNewContact: isNew } }];

